    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We search for parameters that yield a rich residue set (specifically, all even residues modulo M).
# This boosts difficulty by increasing M while ensuring the enumeration window is large enough.
def try_instance():
    mod_pow = rng.randint(6, 10)  # M in [64, 1024]
    M = 1 << mod_pow
    # Choose a sufficiently large window to expose many residues
    n_min = rng.randint(80, 200)
    n_max = n_min + rng.randint(1600, 2600)
    # Enumerate residues efficiently by incremental factorial
    residues = set()
    fact = 1
    for i in range(1, n_max + 1):
        fact *= i
        if i >= n_min:
            P = (i + 1) * (i + 2)
            # Floor division
            F = fact // P
            residues.add(F % M)
            # Early exit if we've already achieved all even residues
            if len(residues) == M // 2 and residues == set(range(0, M, 2)):
                break
    return mod_pow, n_min, n_max, residues
